71	// DeleteWebhookEndpoint removes an endpoint and its pending deliveries.
72	func (s *Store) DeleteWebhookEndpoint(id string) error {
73		s.mu.Lock()
74		defer s.mu.Unlock()
75		if _, ok := s.endpoints[id]; !ok {
76			return ErrNotFound
77		}
78		delete(s.endpoints, id)
79		for did, d := range s.delivs {
80			if d.EndpointID == id && d.Status == DeliveryPending {
81				delete(s.delivs, did)
82			}
83		}
84		return nil
85	}
