// deliver makes an attempt at a delivery and reports whether it made one. A delivery whose endpoint is disabled or gone, or
// whose event is gone, fails without an attempt.
func (s *Service) deliver(ctx context.Context, d store.Delivery) bool {
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	switch {
	case !ok || !ep.Enabled:
		s.failUnsent(d, errDisabled)
		return false
	case !eok:
		s.failUnsent(d, "the event no longer exists")
		return false
	}
	status, errText := s.send(ctx, ep, e)
	now := s.clock.Now()
	gone := status == http.StatusGone
	updated, err := s.store.UpdateDelivery(d.ID, func(x *store.Delivery) error {
		x.Attempts++
		x.LastAttemptAt = &now
		x.NextAttemptAt = nil
		x.ResponseStatus = status
		x.Error = errText
		switch {
		case errText == "":
			x.Status = store.DeliverySucceeded
		case gone || x.Attempts == maxAttempts:
			x.Status = store.DeliveryFailed
		default:
			x.Status = store.DeliveryPending
			next := now.Add(retryDelays[x.Attempts-1])
