func TestFailingEndpointEmailedOncePerDay(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep := failingEndpoint(t, e, "https://hooks.acme.example/down")
	e.HTTP.Respond = func(apitest.Request) (int, error) { return 0, errors.New("no route to host") }
	for _, typ := range []string{"customer.created", "customer.updated"} {
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, typ, map[string]string{}); err != nil {
			t.Fatal(err)
		}
	}
	runSchedule(t, e)
	for _, d := range e.Store.Deliveries(e.Acme.ID, ep.ID) {
		if d.Status != store.DeliveryFailed || d.Attempts != 7 {
			t.Fatalf("delivery = %+v", d)
		}
	}
	msgs := e.Mail.Messages()
	if len(msgs) != 1 || msgs[0].To != "owner@acme.example" || msgs[0].Subject != "Webhook endpoint failing: "+ep.URL {
		t.Fatalf("emails = %+v, want one to the owner", msgs)
	}

	// Another endpoint failing for good the same day is emailed too: the limit is per endpoint.
	other := failingEndpoint(t, e, "https://hooks.acme.example/other")
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{}); err != nil {
		t.Fatal(err)
	}
	runSchedule(t, e)
	if got := e.Store.Deliveries(e.Acme.ID, other.ID)[0]; got.Status != store.DeliveryFailed {
		t.Fatalf("other endpoint's delivery = %+v", got)
	}
	if n := len(e.Mail.Messages()); n != 2 {
		t.Fatalf("emails = %d, want 2 (one per endpoint)", n)
	}

	// The first endpoint fails for good again within 24 hours of its email: no new email. Two days later it is emailed again.
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.updated", map[string]string{}); err != nil {
		t.Fatal(err)
	}
	runSchedule(t, e)
	if n := len(e.Mail.Messages()); n != 2 {
		t.Fatalf("emails = %d, want 2 (at most one per day)", n)
	}
	e.Clock.Advance(48 * time.Hour)
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.updated", map[string]string{}); err != nil {
		t.Fatal(err)
	}
	runSchedule(t, e)
	if n := len(e.Mail.Messages()); n != 3 {
		t.Fatalf("emails = %d, want 3 (a new day, a new email)", n)
	}
}

