func TestDeliveryJSON(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep := failingEndpoint(t, e, "https://hooks.acme.example/json", "*")
	path := "/v1/webhook-endpoints/" + ep.ID + "/deliveries"
	delivery := func() map[string]any {
		t.Helper()
		items := e.Do("GET", path, e.Acme.Key, nil).Map(t)["items"].([]any)
		if len(items) != 1 {
			t.Fatalf("deliveries = %v", items)
		}
		return items[0].(map[string]any)
	}

	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{}); err != nil {
		t.Fatal(err)
	}
	_, _ = e.Webhooks.RunDue(ctx)
	d := delivery()
	if d["status"] != "pending" || d["attempts"] != float64(1) || d["response_status"] != float64(500) || d["error"] == nil ||
		d["next_attempt_at"] != e.Clock.Now().Add(time.Minute).Format(time.RFC3339Nano) || d["last_attempt_at"] == nil {
		t.Fatalf("failed attempt: %v", d)
	}

	e.HTTP.Respond = nil
	e.Clock.Advance(time.Minute)
	_, _ = e.Webhooks.RunDue(ctx)
	d = delivery()
	if v, ok := d["next_attempt_at"]; !ok || v != nil || d["status"] != "succeeded" || d["attempts"] != float64(2) || d["error"] != nil {
		t.Fatalf("succeeded: %v", d)
	}
}
