1	// Package webhooks sends an organization's events to its webhook endpoints.
2	package webhooks
3	
4	import (
5		"bytes"
6		"context"
7		"crypto/hmac"
8		"crypto/sha256"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"io"
14		"net"
15		"net/http"
16		"net/url"
17		"slices"
18		"sync"
19		"time"
20	
21		"example.com/tally/internal/clock"
22		"example.com/tally/internal/mail"
23		"example.com/tally/internal/store"
24	)
25	
26	// Doer sends HTTP requests (an *http.Client).
27	type Doer interface {
28		Do(*http.Request) (*http.Response, error)
29	}
30	
31	// Resolver looks up host names (a *net.Resolver).
32	type Resolver interface {
33		LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error)
34	}
35	
36	// Options configure a Service.
37	type Options struct {
38		Store *store.Store
39		Clock clock.Clock
40		// Doer sends the deliveries; nil means an HTTP client with a 10 second timeout that does not follow redirects.
41		Doer Doer
42		// Resolver checks endpoint hosts; nil means net.DefaultResolver.
43		Resolver Resolver
44		// Mail sends the emails about failing endpoints; nil means no emails are sent.
45		Mail mail.Sender
46	}
47	
48	// Service manages endpoints' URLs and sends deliveries.
49	type Service struct {
50		store    *store.Store
51		clock    clock.Clock
52		doer     Doer
53		resolver Resolver
54		mail     mail.Sender
55	
56		mu     sync.Mutex
57		mailed map[string]time.Time // when each endpoint was last emailed about failing deliveries
58	}
59	
60	// retryDelays are the waits before the second to seventh attempts of a delivery, each counted from the failed attempt before it.
61	var retryDelays = []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
62	
63	// maxAttempts is how many attempts a delivery gets before it fails for good.
64	const maxAttempts = 7
65	
66	// mailEvery is the least time between two emails about the same endpoint.
67	const mailEvery = 24 * time.Hour
68	
69	// errDisabled is why a delivery to a disabled or deleted endpoint fails without being sent.
70	const errDisabled = "the endpoint is disabled or was deleted"
71	
72	// New returns a Service.
73	func New(opt Options) *Service {
74		s := &Service{store: opt.Store, clock: opt.Clock, doer: opt.Doer, resolver: opt.Resolver, mail: opt.Mail, mailed: map[string]time.Time{}}
75		if s.clock == nil {
76			s.clock = clock.Real{}
77		}
78		if s.doer == nil {
79			s.doer = &http.Client{Timeout: 10 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
80		}
81		if s.resolver == nil {
82			s.resolver = net.DefaultResolver
83		}
84		return s
85	}
86	
87	// EventTypes are the events Tally sends. An endpoint subscribes to some of them, or to "*" for all.
88	var EventTypes = []string{
89		"customer.created", "customer.updated", "customer.deleted",
90		"subscription.created", "subscription.updated", "subscription.canceled",
91		"invoice.created", "invoice.paid", "invoice.payment_failed", "invoice.voided",
92	}
93	
94	// Errors.
95	var (
96		ErrInvalidURL    = errors.New("invalid webhook URL")
97		ErrInvalidEvents = errors.New("invalid event types")
98	)
99	
100	// CheckURL checks a webhook URL before it is saved: an absolute http or https URL whose host resolves.
101	func (s *Service) CheckURL(ctx context.Context, raw string) error {
102		u, err := url.Parse(raw)
103		if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
104			return fmt.Errorf("%w: use an absolute http or https URL", ErrInvalidURL)
105		}
106		host := u.Hostname()
107		if net.ParseIP(host) != nil {
108			return nil
109		}
110		addrs, err := s.resolver.LookupIPAddr(ctx, host)
111		if err != nil || len(addrs) == 0 {
112			return fmt.Errorf("%w: the host %q does not resolve", ErrInvalidURL, host)
113		}
114		return nil
115	}
116	
117	// CheckEvents checks an endpoint's event types.
118	func CheckEvents(types []string) error {
119		if len(types) == 0 {
120			return fmt.Errorf("%w: name at least one event type, or \"*\"", ErrInvalidEvents)
121		}
122		for _, t := range types {
123			if t != "*" && !slices.Contains(EventTypes, t) {
124				return fmt.Errorf("%w: unknown event type %q", ErrInvalidEvents, t)
125			}
126		}
127		return nil
128	}
129	
130	// NewSecret returns a new signing secret for an endpoint.
131	func NewSecret() string { return store.NewToken("whsec_") }
132	
133	// Sign returns the signature of a delivery's body: the hex HMAC-SHA256 of the body, keyed with the endpoint's secret.
134	func Sign(secret string, body []byte) string {
135		m := hmac.New(sha256.New, []byte(secret))
136		m.Write(body)
137		return hex.EncodeToString(m.Sum(nil))
138	}
139	
140	// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
141	// type. The deliveries are sent by RunDue.
142	func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
143		raw, err := json.Marshal(data)
144		if err != nil {
145			return err
146		}
147		now := s.clock.Now()
148		e, err := s.store.AddEvent(orgID, eventType, raw, now)
149		if err != nil {
150			return err
151		}
152		for _, ep := range s.store.WebhookEndpoints(orgID) {
153			if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
154				continue
155			}
156			next := now
157			if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
158				return err
159			}
160		}
161		return nil
162	}
163	
164	// RunDue attempts every delivery that is due at the clock's time and returns how many attempts it made. An answer with a 2xx
165	// status marks a delivery succeeded. A failed attempt leaves it pending for a later attempt (see retryDelays) until the
166	// last one fails, and a 410 Gone answer fails it at once.
167	func (s *Service) RunDue(ctx context.Context) (int, error) {
168		n := 0
169		for _, d := range s.store.DueDeliveries(s.clock.Now()) {
170			if err := ctx.Err(); err != nil {
171				return n, err
172			}
173			if s.deliver(ctx, d) {
174				n++
175			}
176		}
177		return n, nil
178	}
179	
180	// Body is what a delivery POSTs.
181	type Body struct {
182		ID        string          `json:"id"`
183		Type      string          `json:"type"`
184		CreatedAt time.Time       `json:"created_at"`
185		Data      json.RawMessage `json:"data"`
186	}
187	
188	// deliver makes an attempt at a delivery and reports whether it made one. A delivery whose endpoint is disabled or gone, or
189	// whose event is gone, fails without an attempt.
190	func (s *Service) deliver(ctx context.Context, d store.Delivery) bool {
191		ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
192		e, eok := s.store.EventByID(d.EventID)
193		switch {
194		case !ok || !ep.Enabled:
195			s.failUnsent(d, errDisabled)
196			return false
197		case !eok:
198			s.failUnsent(d, "the event no longer exists")
199			return false
200		}
201		status, errText := s.send(ctx, ep, e)
202		now := s.clock.Now()
203		gone := status == http.StatusGone
204		updated, err := s.store.UpdateDelivery(d.ID, func(x *store.Delivery) error {
205			x.Attempts++
206			x.LastAttemptAt = &now
207			x.NextAttemptAt = nil
208			x.ResponseStatus = status
209			x.Error = errText
210			switch {
211			case errText == "":
212				x.Status = store.DeliverySucceeded
213			case gone || x.Attempts == maxAttempts:
214				x.Status = store.DeliveryFailed
215			default:
216				x.Status = store.DeliveryPending
217				next := now.Add(retryDelays[x.Attempts-1])
218				x.NextAttemptAt = &next
219			}
220			return nil
221		})
222		if err != nil {
223			return true // the delivery was deleted with its endpoint while it was sent
224		}
225		if gone {
226			s.goneEndpoint(d.OrgID, d.EndpointID)
227		}
228		if updated.Status == store.DeliveryFailed && updated.Attempts == maxAttempts {
229			s.mailOwners(ctx, d.OrgID, ep, errText)
230		}
231		return true
232	}
233	
234	// failUnsent fails a delivery for good without sending it.
235	func (s *Service) failUnsent(d store.Delivery, errText string) {
236		_, _ = s.store.UpdateDelivery(d.ID, func(x *store.Delivery) error {
237			x.Status = store.DeliveryFailed
238			x.NextAttemptAt = nil
239			x.Error = errText
240			return nil
241		})
242	}
243	
244	// goneEndpoint disables an endpoint that answered 410 Gone and fails its pending deliveries, which are not sent.
245	func (s *Service) goneEndpoint(orgID, endpointID string) {
246		_, _ = s.store.UpdateWebhookEndpoint(orgID, endpointID, func(ep *store.WebhookEndpoint) error {
247			ep.Enabled = false
248			ep.DisabledReason = "gone"
249			return nil
250		})
251		for _, d := range s.store.Deliveries(orgID, endpointID) {
252			if d.Status == store.DeliveryPending {
253				s.failUnsent(d, errDisabled)
254			}
255		}
256	}
