258	// mailOwners emails every owner of the organization that deliveries to the endpoint are failing. It sends at most one such
259	// email per endpoint in mailEvery.
260	func (s *Service) mailOwners(ctx context.Context, orgID string, ep store.WebhookEndpoint, lastErr string) {
261		if s.mail == nil {
262			return
263		}
264		now := s.clock.Now()
265		s.mu.Lock()
266		if last, ok := s.mailed[ep.ID]; ok && now.Sub(last) < mailEvery {
267			s.mu.Unlock()
268			return
269		}
270		s.mailed[ep.ID] = now
271		s.mu.Unlock()
272		body := fmt.Sprintf("Tally could not deliver an event to %s after %d attempts. The last attempt failed: %s.\n\nThe endpoint is still enabled; Tally keeps the events that are not delivered.", ep.URL, maxAttempts, lastErr)
273		for _, m := range s.store.Members(orgID) {
274			if u, ok := s.store.User(m.UserID); ok && m.Role == store.RoleOwner {
275				_ = s.mail.Send(ctx, mail.Message{To: u.Email, Subject: "Webhook endpoint failing: " + ep.URL, Body: body})
276			}
277		}
278	}
